import{Z as o,e as i,f as n,a0 as t}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Conditions","description":"","frontmatter":{},"headers":[],"relativePath":"forms/conditions.md","filePath":"forms/conditions.md","lastUpdated":1782532814000}'),s={name:"forms/conditions.md"};function a(r,e,l,d,h,c){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For statuses plus conditions in one workflow story, see <a href="/guides/submissions-workflows/submission-statuses-and-conditional-workflows">Submission statuses and conditional workflows</a>.</p></div><p>Conditions let a form change what happens based on answers already given.</p><p>They are useful when the form should react to the person filling it out, instead of showing the same path to everyone. A simple form can show the same fields to everyone, but a longer form often works better when it can reveal, skip, or hold back parts of the flow depending on what someone has already entered.</p><p>In Formie, conditions can be added in a few different places:</p><ul><li>fields, to show or hide them</li><li>pages, to skip entire sections of a multi-page form</li><li>page buttons, to control whether someone can move on</li><li>email notifications, to decide whether they should send</li><li>notification recipients, to choose who should receive an email</li></ul><p>That makes conditions one of the simplest ways to keep a form focused instead of overwhelming.</p><p>Every condition is built from three parts:</p><ol><li>the field to check</li><li>the comparison to use</li><li>the value to compare against</li></ol><p>You can then choose whether all rules must match or whether any one of them is enough.</p><h2 id="common-uses" tabindex="-1">Common Uses <a class="header-anchor" href="#common-uses" aria-label="Permalink to &quot;Common Uses&quot;">​</a></h2><p>On fields, conditions are usually about relevance. A common example is only showing an <code>Other</code> text field when someone selected <code>Other</code> earlier in the form.</p><p>On pages, conditions are usually about path. This lets one form branch into different routes, skipping pages that do not apply.</p><p>Page buttons can also respond to conditions. That is useful when someone should not move to the next page until the form is in the right state, without needing to add another page just to handle that decision.</p><p>Conditions are also available on notifications. You can decide whether a notification should send at all, or use recipient conditions when the email should go to different people depending on the submission.</p><h2 id="hidden-required-fields" tabindex="-1">Hidden Required Fields <a class="header-anchor" href="#hidden-required-fields" aria-label="Permalink to &quot;Hidden Required Fields&quot;">​</a></h2><p>If a required field is hidden by conditions, Formie stops treating it as required while it is hidden.</p><p>That avoids the common problem of a form being blocked by a field the person cannot even see.</p><h2 id="control-panel-submissions" tabindex="-1">Control Panel Submissions <a class="header-anchor" href="#control-panel-submissions" aria-label="Permalink to &quot;Control Panel Submissions&quot;">​</a></h2><p>When editing a submission in the control panel, Formie can apply the same field and page conditions used on the front end. Configure the default under <strong>Formie → Settings → Submissions</strong>, or override per form. See <a href="/submissions/submissions#edit-submissions-in-the-control-panel">Submissions</a>.</p>',20)])])}const u=o(s,[["render",a]]);export{m as __pageData,u as default};
